import { useState, useEffect, useCallback } from 'react'
import './App.css'

const BTC_FEED_ID = '0xe62df6c8b4a85fe1a67db44dc12de5db330f7ac66b72dc658afedf0f4a415b43'
const HERMES_API = 'https://hermes.pyth.network/v2/updates/price/latest'

function App() {
  const [currentPrice, setCurrentPrice] = useState(null)
  const [gameState, setGameState] = useState('waiting') // waiting, playing, result
  const [timeLeft, setTimeLeft] = useState(60)
  const [prediction, setPrediction] = useState(null)
  const [score, setScore] = useState(0)
  const [roundStartPrice, setRoundStartPrice] = useState(null)
  const [lastResult, setLastResult] = useState(null)
  const [priceChange, setPriceChange] = useState(0)
  const [isLoading, setIsLoading] = useState(true)

  // Fetch Bitcoin price from Pyth Hermes API
  const fetchPrice = useCallback(async () => {
    try {
      const response = await fetch(`${HERMES_API}?ids[]=${BTC_FEED_ID}`)
      const data = await response.json()

      if (data.parsed && data.parsed[0]) {
        const priceData = data.parsed[0].price
        const price = parseInt(priceData.price) * Math.pow(10, priceData.expo)
        setCurrentPrice(price)
        setIsLoading(false)
        return price
      }
    } catch (error) {
      console.error('Error fetching price:', error)
    }
  }, [])

  // Start a new round
  const startRound = useCallback(async () => {
    const price = await fetchPrice()
    setRoundStartPrice(price)
    setGameState('playing')
    setTimeLeft(60)
    setPrediction(null)
    setLastResult(null)
    setPriceChange(0)
  }, [fetchPrice])

  // Make prediction
  const makePrediction = (direction) => {
    if (gameState === 'playing' && !prediction) {
      setPrediction(direction)
    }
  }

  // End round and calculate result
  const endRound = useCallback(async () => {
    const endPrice = await fetchPrice()
    const actualChange = endPrice - roundStartPrice
    const actualDirection = actualChange > 0 ? 'up' : 'down'

    setPriceChange(actualChange)

    if (prediction && prediction === actualDirection) {
      setScore(prev => prev + 10)
      setLastResult('correct')
    } else if (prediction) {
      setLastResult('wrong')
    } else {
      setLastResult('no-prediction')
    }

    setGameState('result')

    // Auto-start next round after 3 seconds
    setTimeout(() => {
      startRound()
    }, 3000)
  }, [roundStartPrice, prediction, startRound, fetchPrice])

  // Timer countdown
  useEffect(() => {
    if (gameState === 'playing' && timeLeft > 0) {
      const timer = setTimeout(() => {
        setTimeLeft(prev => prev - 1)
      }, 1000)
      return () => clearTimeout(timer)
    } else if (gameState === 'playing' && timeLeft === 0) {
      endRound()
    }
  }, [gameState, timeLeft, endRound])

  // Update price every 2 seconds during game
  useEffect(() => {
    if (gameState === 'playing') {
      const interval = setInterval(fetchPrice, 2000)
      return () => clearInterval(interval)
    }
  }, [gameState, fetchPrice])

  // Initial price fetch
  useEffect(() => {
    fetchPrice()
  }, [fetchPrice])

  const formatPrice = (price) => {
    return price ? `$${price.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` : '...'
  }

  const formatChange = (change) => {
    const sign = change > 0 ? '+' : ''
    return `${sign}$${change.toFixed(2)}`
  }

  if (isLoading) {
    return (
      <div className="app">
        <div className="loading">
          <h1>🚀 Bonjour</h1>
          <p>Loading Bitcoin price...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="app">
      <header className="header">
        <h1>🚀 Bonjour</h1>
        <p>Bitcoin Price Prediction Game</p>
        <div className="score">Score: {score}</div>
      </header>

      <main className="game">
        <div className="price-display">
          <div className="current-price">
            <span className="label">Current BTC Price</span>
            <span className="price">{formatPrice(currentPrice)}</span>
          </div>

          {gameState === 'playing' && roundStartPrice && (
            <div className="round-info">
              <span className="start-price">Started at: {formatPrice(roundStartPrice)}</span>
              <span className={`live-change ${currentPrice > roundStartPrice ? 'positive' : 'negative'}`}>
                {formatChange(currentPrice - roundStartPrice)}
              </span>
            </div>
          )}
        </div>

        {gameState === 'waiting' && (
          <div className="waiting">
            <h2>Ready to play?</h2>
            <p>Predict if Bitcoin will go UP or DOWN in the next 60 seconds!</p>
            <button className="start-btn" onClick={startRound}>
              Start Game
            </button>
          </div>
        )}

        {gameState === 'playing' && (
          <div className="playing">
            <div className="timer">
              <span className="time">{timeLeft}s</span>
              <div className="timer-bar">
                <div 
                  className="timer-fill" 
                  style={{ width: `${(timeLeft / 60) * 100}%` }}
                ></div>
              </div>
            </div>

            <div className="prediction-section">
              <h2>Will Bitcoin go UP or DOWN?</h2>
              {!prediction ? (
                <div className="prediction-buttons">
                  <button 
                    className="predict-btn up" 
                    onClick={() => makePrediction('up')}
                  >
                    📈 UP
                  </button>
                  <button 
                    className="predict-btn down" 
                    onClick={() => makePrediction('down')}
                  >
                    📉 DOWN
                  </button>
                </div>
              ) : (
                <div className="prediction-made">
                  <p>You predicted: <strong>{prediction.toUpperCase()}</strong></p>
                  <p>Wait for round to end...</p>
                </div>
              )}
            </div>
          </div>
        )}

        {gameState === 'result' && (
          <div className="result">
            <div className={`result-card ${lastResult}`}>
              {lastResult === 'correct' && (
                <>
                  <h2>🎉 Correct!</h2>
                  <p>You predicted <strong>{prediction.toUpperCase()}</strong></p>
                  <p>Bitcoin moved {formatChange(priceChange)}</p>
                  <p className="points">+10 points!</p>
                </>
              )}
              {lastResult === 'wrong' && (
                <>
                  <h2>❌ Wrong</h2>
                  <p>You predicted <strong>{prediction.toUpperCase()}</strong></p>
                  <p>Bitcoin moved {formatChange(priceChange)}</p>
                  <p className="points">No points</p>
                </>
              )}
              {lastResult === 'no-prediction' && (
                <>
                  <h2>⏰ Time's up!</h2>
                  <p>You didn't make a prediction</p>
                  <p>Bitcoin moved {formatChange(priceChange)}</p>
                </>
              )}
            </div>
            <p className="next-round">Next round starting in 3 seconds...</p>
          </div>
        )}
      </main>

      <footer className="footer">
        <p>Powered by Pyth Network</p>
      </footer>
    </div>
  )
}

export default App

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', sans-serif;
  min-height: 100vh;
}

.app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  padding: 20px;
  max-width: 600px;
  margin: 0 auto;
}

.loading {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 50vh;
  text-align: center;
}

.loading h1 {
  font-size: 3rem;
  margin-bottom: 1rem;
}

.loading p {
  font-size: 1.2rem;
  opacity: 0.8;
}

.header {
  text-align: center;
  margin-bottom: 2rem;
}

.header h1 {
  font-size: 3rem;
  margin-bottom: 0.5rem;
  text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
}

.header p {
  font-size: 1.2rem;
  opacity: 0.9;
  margin-bottom: 1rem;
}

.score {
  background: rgba(255,255,255,0.2);
  padding: 0.8rem 1.5rem;
  border-radius: 25px;
  font-size: 1.3rem;
  font-weight: bold;
  display: inline-block;
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255,255,255,0.3);
}

.game {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.price-display {
  background: rgba(255,255,255,0.15);
  padding: 2rem;
  border-radius: 20px;
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255,255,255,0.2);
  text-align: center;
}

.current-price {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.label {
  font-size: 1.1rem;
  opacity: 0.8;
}

.price {
  font-size: 2.5rem;
  font-weight: bold;
  font-family: 'Monaco', 'Consolas', monospace;
}

.round-info {
  margin-top: 1.5rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.start-price {
  font-size: 1rem;
  opacity: 0.8;
}

.live-change {
  font-size: 1.2rem;
  font-weight: bold;
  padding: 0.5rem 1rem;
  border-radius: 10px;
  font-family: 'Monaco', 'Consolas', monospace;
}

.live-change.positive {
  background: rgba(34, 197, 94, 0.3);
  color: #86efac;
}

.live-change.negative {
  background: rgba(239, 68, 68, 0.3);
  color: #fca5a5;
}

.waiting {
  text-align: center;
  background: rgba(255,255,255,0.1);
  padding: 3rem 2rem;
  border-radius: 20px;
  backdrop-filter: blur(10px);
}

.waiting h2 {
  font-size: 2rem;
  margin-bottom: 1rem;
}

.waiting p {
  font-size: 1.2rem;
  margin-bottom: 2rem;
  opacity: 0.9;
}

.start-btn {
  background: linear-gradient(45deg, #10b981, #059669);
  color: white;
  border: none;
  padding: 1rem 2rem;
  border-radius: 50px;
  font-size: 1.2rem;
  font-weight: bold;
  cursor: pointer;
  transition: transform 0.2s, box-shadow 0.2s;
  box-shadow: 0 8px 25px rgba(16, 185, 129, 0.3);
}

.start-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 35px rgba(16, 185, 129, 0.4);
}

.playing {
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.timer {
  text-align: center;
}

.time {
  font-size: 3rem;
  font-weight: bold;
  display: block;
  margin-bottom: 1rem;
}

.timer-bar {
  width: 100%;
  height: 8px;
  background: rgba(255,255,255,0.2);
  border-radius: 4px;
  overflow: hidden;
}

.timer-fill {
  height: 100%;
  background: linear-gradient(90deg, #ef4444, #f97316, #eab308);
  transition: width 1s linear;
  border-radius: 4px;
}

.prediction-section {
  background: rgba(255,255,255,0.1);
  padding: 2rem;
  border-radius: 20px;
  text-align: center;
}

.prediction-section h2 {
  font-size: 1.8rem;
  margin-bottom: 2rem;
}

.prediction-buttons {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
}

.predict-btn {
  background: rgba(255,255,255,0.2);
  color: white;
  border: 2px solid rgba(255,255,255,0.3);
  padding: 1.5rem 2rem;
  border-radius: 15px;
  font-size: 1.3rem;
  font-weight: bold;
  cursor: pointer;
  transition: all 0.3s;
  backdrop-filter: blur(10px);
  min-width: 120px;
}

.predict-btn:hover {
  transform: translateY(-3px);
  box-shadow: 0 10px 25px rgba(0,0,0,0.2);
}

.predict-btn.up:hover {
  background: rgba(34, 197, 94, 0.4);
  border-color: #22c55e;
}

.predict-btn.down:hover {
  background: rgba(239, 68, 68, 0.4);
  border-color: #ef4444;
}

.prediction-made {
  background: rgba(255,255,255,0.15);
  padding: 2rem;
  border-radius: 15px;
}

.prediction-made p {
  font-size: 1.2rem;
  margin-bottom: 0.5rem;
}

.prediction-made strong {
  color: #fbbf24;
}

.result {
  text-align: center;
}

.result-card {
  background: rgba(255,255,255,0.15);
  padding: 3rem 2rem;
  border-radius: 20px;
  margin-bottom: 1rem;
  backdrop-filter: blur(10px);
}

.result-card.correct {
  border: 2px solid #22c55e;
  background: rgba(34, 197, 94, 0.2);
}

.result-card.wrong {
  border: 2px solid #ef4444;
  background: rgba(239, 68, 68, 0.2);
}

.result-card h2 {
  font-size: 2.5rem;
  margin-bottom: 1rem;
}

.result-card p {
  font-size: 1.2rem;
  margin-bottom: 0.8rem;
}

.points {
  font-size: 1.5rem;
  font-weight: bold;
  color: #fbbf24;
}

.next-round {
  font-size: 1.1rem;
  opacity: 0.8;
  animation: pulse 2s infinite;
}

.footer {
  text-align: center;
  margin-top: 2rem;
  padding-top: 1rem;
  opacity: 0.7;
}

@keyframes pulse {
  0%, 100% { opacity: 0.5; }
  50% { opacity: 1; }
}

@media (max-width: 640px) {
  .app {
    padding: 15px;
  }

  .header h1 {
    font-size: 2.5rem;
  }

  .price {
    font-size: 2rem;
  }

  .prediction-buttons {
    flex-direction: column;
    align-items: center;
  }

  .predict-btn {
    width: 100%;
    max-width: 200px;
  }

  .round-info {
    flex-direction: column;
    text-align: center;
  }
}

